# Managed by Orbit: Node Caddy build
{
    auto_https disable_certs
    order abort first
    metrics {
        per_host
    }
}

# orbit: gateway gateway.orbit
gateway.orbit, 10.231.0.1 {
    bind 10.231.0.1
    @orbit_outside not remote_ip 10.231.0.0/24
    abort @orbit_outside
    tls /etc/caddy/orbit-cert-current/gateway.pem /etc/caddy/orbit-cert-current/gateway.key
    encode zstd gzip

    @gateway path /api/* /mcp /mcp/* /up /.well-known/* /horizon /horizon/*
    handle @gateway {
        root * /home/orbit/swamp-proof/src/apps/gateway/public
        php_fastcgi unix//run/php/orbit-gateway.sock {
            resolve_root_symlink
            dial_timeout 10s
            read_timeout 600s
            write_timeout 600s
            flush_interval 1ms
        }
    }

    handle /vendor/horizon-new-dawn/* {
        root * /home/orbit/swamp-proof/src/apps/gateway/public
        file_server
    }

    handle_path /grafana/* {
        forward_auth unix//run/php/orbit-gateway.sock {
            uri /index.php
            transport fastcgi {
                root /home/orbit/swamp-proof/src/apps/gateway/public
                resolve_root_symlink
                split .php
                env REQUEST_URI /api/v1/metrics/grafana/authorize
                env REMOTE_ADDR {remote_host}
            }
        }
        reverse_proxy https://10.231.0.1 {
            header_up Host metrics.orbit
            transport http {
                tls_server_name metrics.orbit
                tls_trusted_ca_certs /etc/caddy/orbit-cert-current/root-ca.pem
            }
        }
    }

    handle /assets/* {
        root * /home/orbit/web/current
        @asset file
        header @asset Cache-Control "public, max-age=31536000, immutable"
        @missing not file
        header @missing Cache-Control "no-cache"
        file_server
    }

    handle {
        root * /home/orbit/web/current
        header Cache-Control "no-cache"
        try_files {path} /index.html
        file_server
    }
}

# orbit: app-dev route-1
https://swamp.orbit {
    bind 10.231.0.1
    tls /etc/caddy/orbit-certificates/route-1/current/cert.pem /etc/caddy/orbit-certificates/route-1/current/key.pem
    reverse_proxy 127.0.0.1:9418 {
    flush_interval -1
    transport http {
        read_timeout 1h
        response_header_timeout 1h
    }
}
}

# orbit: websocket reverb.orbit
# Managed by Orbit: websocket
reverb.orbit {
    bind 10.231.0.1
    @orbit_outside not remote_ip 10.231.0.0/24
    abort @orbit_outside
    tls /etc/caddy/orbit-websocket-cert-current/reverb.pem /etc/caddy/orbit-websocket-cert-current/reverb.key
    handle /internal/* {
        respond 403
    }
    handle {
        reverse_proxy 127.0.0.1:8790
    }
}

